1178	static void
1179	eterm_calc_es(void)
1180	{
1181	  int i;
1182	  for (i = 0; i < sweep_points; i++) {
1183	    // z=1/(jwc*z0) = 1/(2*pi*f*c*z0)  Note: normalized with Z0
1184	    // s11ao = (z-1)/(z+1) = (1-1/z)/(1+1/z) = (1-jwcz0)/(1+jwcz0)
1185	    // prepare 1/s11ao for effeiciency
1186	    float c = 50e-15;
1187	    //float c = 1.707e-12;
1188	    float z0 = 50;
1189	    float z = 2 * VNA_PI * frequencies[i] * c * z0;
1190	    float sq = 1 + z*z;
1191	    float s11aor = (1 - z*z) / sq;
1192	    float s11aoi = 2*z / sq;
1193	
1194	    // S11mo’= S11mo - Ed
1195	    // S11ms’= S11ms - Ed
1196	    float s11or = cal_data[CAL_OPEN][i][0] - cal_data[ETERM_ED][i][0];
1197	    float s11oi = cal_data[CAL_OPEN][i][1] - cal_data[ETERM_ED][i][1];
1198	    float s11sr = cal_data[CAL_SHORT][i][0] - cal_data[ETERM_ED][i][0];
1199	    float s11si = cal_data[CAL_SHORT][i][1] - cal_data[ETERM_ED][i][1];
1200	    // Es = (S11mo'/s11ao + S11ms’)/(S11mo' - S11ms’)
1201	    float numr = s11sr + s11or * s11aor - s11oi * s11aoi;
1202	    float numi = s11si + s11oi * s11aor + s11or * s11aoi;
1203	    float denomr = s11or - s11sr;
1204	    float denomi = s11oi - s11si;
1205	    sq = denomr*denomr+denomi*denomi;
1206	    cal_data[ETERM_ES][i][0] = (numr*denomr + numi*denomi)/sq;
1207	    cal_data[ETERM_ES][i][1] = (numi*denomr - numr*denomi)/sq;
1208	  }
1209	  cal_status &= ~CALSTAT_OPEN;
1210	  cal_status |= CALSTAT_ES;
1211	}
