1213	static void
1214	eterm_calc_er(int sign)
1215	{
1216	  int i;
1217	  for (i = 0; i < sweep_points; i++) {
1218	    // Er = sign*(1-sign*Es)S11ms'
1219	    float s11sr = cal_data[CAL_SHORT][i][0] - cal_data[ETERM_ED][i][0];
1220	    float s11si = cal_data[CAL_SHORT][i][1] - cal_data[ETERM_ED][i][1];
1221	    float esr = cal_data[ETERM_ES][i][0];
1222	    float esi = cal_data[ETERM_ES][i][1];
1223	    if (sign > 0) {
1224	      esr = -esr;
1225	      esi = -esi;
1226	    }
1227	    esr = 1 + esr;
1228	    float err = esr * s11sr - esi * s11si;
1229	    float eri = esr * s11si + esi * s11sr;
1230	    if (sign < 0) {
1231	      err = -err;
1232	      eri = -eri;
1233	    }
1234	    cal_data[ETERM_ER][i][0] = err;
1235	    cal_data[ETERM_ER][i][1] = eri;
1236	  }
1237	  cal_status &= ~CALSTAT_SHORT;
1238	  cal_status |= CALSTAT_ER;
1239	}
