1241	// CAUTION: Et is inversed for efficiency
1242	static void
1243	eterm_calc_et(void)
1244	{
1245	  int i;
1246	  for (i = 0; i < sweep_points; i++) {
1247	    // Et = 1/(S21mt - Ex)
1248	    float etr = cal_data[CAL_THRU][i][0] - cal_data[CAL_ISOLN][i][0];
1249	    float eti = cal_data[CAL_THRU][i][1] - cal_data[CAL_ISOLN][i][1];
1250	    float sq = etr*etr + eti*eti;
1251	    float invr = etr / sq;
1252	    float invi = -eti / sq;
1253	    cal_data[ETERM_ET][i][0] = invr;
1254	    cal_data[ETERM_ET][i][1] = invi;
1255	  }
1256	  cal_status &= ~CALSTAT_THRU;
1257	  cal_status |= CALSTAT_ET;
1258	}
