1294	static void apply_error_term_at(int i)
1295	{
1296	    // S11m' = S11m - Ed
1297	    // S11a = S11m' / (Er + Es S11m')
1298	    float s11mr = measured[0][i][0] - cal_data[ETERM_ED][i][0];
1299	    float s11mi = measured[0][i][1] - cal_data[ETERM_ED][i][1];
1300	    float err = cal_data[ETERM_ER][i][0] + s11mr * cal_data[ETERM_ES][i][0] - s11mi * cal_data[ETERM_ES][i][1];
1301	    float eri = cal_data[ETERM_ER][i][1] + s11mr * cal_data[ETERM_ES][i][1] + s11mi * cal_data[ETERM_ES][i][0];
1302	    float sq = err*err + eri*eri;
1303	    float s11ar = (s11mr * err + s11mi * eri) / sq;
1304	    float s11ai = (s11mi * err - s11mr * eri) / sq;
1305	    measured[0][i][0] = s11ar;
1306	    measured[0][i][1] = s11ai;
1307	
1308	    // CAUTION: Et is inversed for efficiency
1309	    // S21m' = S21m - Ex
1310	    // S21a = S21m' (1-EsS11a)Et
