1312	    float s21mi = measured[1][i][1] - cal_data[ETERM_EX][i][1];
1313	    float esr = 1 - (cal_data[ETERM_ES][i][0] * s11ar - cal_data[ETERM_ES][i][1] * s11ai);
1314	    float esi = - (cal_data[ETERM_ES][i][1] * s11ar + cal_data[ETERM_ES][i][0] * s11ai);
1315	    float etr = esr * cal_data[ETERM_ET][i][0] - esi * cal_data[ETERM_ET][i][1];
1316	    float eti = esr * cal_data[ETERM_ET][i][1] + esi * cal_data[ETERM_ET][i][0];
1317	    float s21ar = s21mr * etr - s21mi * eti;
1318	    float s21ai = s21mi * etr + s21mr * eti;
1319	    measured[1][i][0] = s21ar;
