1323	static void apply_edelay_at(int i)
1324	{
1325	  float w = 2 * VNA_PI * electrical_delay * frequencies[i] * 1E-12;
1326	  float s = sin(w);
1327	  float c = cos(w);
1328	  float real = measured[0][i][0];
1329	  float imag = measured[0][i][1];
1330	  measured[0][i][0] = real * c - imag * s;
1331	  measured[0][i][1] = imag * c + real * s;
1332	  real = measured[1][i][0];
1333	  imag = measured[1][i][1];
1334	  measured[1][i][0] = real * c - imag * s;
1335	  measured[1][i][1] = imag * c + real * s;
1336	}
